ListNavigationTree/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {TreeList} from '@astryxdesign/core/TreeList';\n\nconst noop = () => {};\n\nexport default function TreeListNavigationTree() {\n  return (\n    <TreeList\n      items={[\n        {\n          id: 'nav',\n          label: 'Navigation',\n          isExpanded: true,\n          children: [\n            {id: 'home', label: 'Home', onClick: noop},\n            {id: 'about', label: 'About', onClick: noop, isSelected: true},\n            {id: 'contact', label: 'Contact', onClick: noop},\n          ],\n        },\n      ]}\n    />\n  );\n}\n","/templates/TypeaheadShowcase/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {Typeahead} from '@astryxdesign/core/Typeahead';\nimport type {SearchableItem, SearchSource} from '@astryxdesign/core/Typeahead';\n\nconst fruits: SearchableItem[] = [\n  {id: '1', label: 'Apple'},\n  {id: '2', label: 'Banana'},\n  {id: '3', label: 'Cherry'},\n  {id: '4', label: 'Date'},\n  {id: '5', label: 'Elderberry'},\n  {id: '6', label: 'Fig'},\n  {id: '7', label: 'Grape'},\n  {id: '8', label: 'Honeydew'},\n];\n\nconst fruitSource: SearchSource = {\n  search: (query: string) =>\n    fruits.filter(f => f.label.toLowerCase().includes(query.toLowerCase())),\n  bootstrap: () => fruits.slice(0, 5),\n};\n\nexport default function TypeaheadShowcase() {\n  const [value, setValue] = useState<SearchableItem | null>(null);\n  return (\n    <div style={{width: 320}}>\n      <Typeahead\n        label=\"Fruit\"\n        placeholder=\"Search fruits...\"\n        searchSource={fruitSource}\n        value={value}\n        onChange={setValue}\n      />\n    </div>\n  );\n}\n","/templates/TypeaheadLimitedResults/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {Typeahead} from '@astryxdesign/core/Typeahead';\nimport type {SearchableItem, SearchSource} from '@astryxdesign/core/Typeahead';\nimport {Center} from '@astryxdesign/core/Center';\n\nconst items: SearchableItem[] = [\n  {id: '1', label: 'United States'},\n  {id: '2', label: 'United Kingdom'},\n  {id: '3', label: 'Canada'},\n  {id: '4', label: 'Australia'},\n  {id: '5', label: 'Germany'},\n  {id: '6', label: 'France'},\n  {id: '7', label: 'Japan'},\n  {id: '8', label: 'Brazil'},\n];\n\nconst searchSource: SearchSource = {\n  search: (query: string) =>\n    items.filter(i => i.label.toLowerCase().includes(query.toLowerCase())),\n  bootstrap: () => items.slice(0, 5),\n};\n\nexport default function TypeaheadLimitedResults() {\n  const [value, setValue] = useState<SearchableItem | null>(null);\n  return (\n    <Center width={320}>\n      <Typeahead\n        label=\"Country\"\n        placeholder=\"Search countries...\"\n        searchSource={searchSource}\n        value={value}\n        onChange={setValue}\n        hasEntriesOnFocus\n        maxMenuItems={3}\n      />\n    </Center>\n  );\n}\n","/templates/TypeaheadSearchField/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {Typeahead} from '@astryxdesign/core/Typeahead';\nimport type {SearchableItem, SearchSource} from '@astryxdesign/core/Typeahead';\nimport {Center} from '@astryxdesign/core/Center';\nimport {MagnifyingGlassIcon} from '@heroicons/react/24/outline';\n\nconst items: SearchableItem[] = [\n  {id: '1', label: 'Olivia Martin'},\n  {id: '2', label: 'Jackson Lee'},\n  {id: '3', label: 'Isabella Nguyen'},\n  {id: '4', label: 'William Kim'},\n  {id: '5', label: 'Sofia Davis'},\n  {id: '6', label: 'Lucas Brown'},\n  {id: '7', label: 'Mia Wilson'},\n  {id: '8', label: 'Ethan Jones'},\n];\n\nconst searchSource: SearchSource = {\n  search: (query: string) =>\n    items.filter(i => i.label.toLowerCase().includes(query.toLowerCase())),\n  bootstrap: () => items.slice(0, 5),\n};\n\nexport default function TypeaheadSearchField() {\n  const [value, setValue] = useState<SearchableItem | null>(null);\n  return (\n    <Center width={320}>\n      <Typeahead\n        label=\"Team member\"\n        placeholder=\"Search people...\"\n        searchSource={searchSource}\n        value={value}\n        onChange={setValue}\n        startIcon={MagnifyingGlassIcon}\n        hasEntriesOnFocus\n      />\n    </Center>\n  );\n}\n","/templates/TypeaheadWithHelperText/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {Typeahead} from '@astryxdesign/core/Typeahead';\nimport type {SearchableItem, SearchSource} from '@astryxdesign/core/Typeahead';\nimport {Center} from '@astryxdesign/core/Center';\n\nconst items: SearchableItem[] = [\n  {id: '1', label: 'Engineering'},\n  {id: '2', label: 'Design'},\n  {id: '3', label: 'Marketing'},\n  {id: '4', label: 'Sales'},\n  {id: '5', label: 'Product'},\n  {id: '6', label: 'Finance'},\n  {id: '7', label: 'Legal'},\n  {id: '8', label: 'Operations'},\n];\n\nconst searchSource: SearchSource = {\n  search: (query: string) =>\n    items.filter(i => i.label.toLowerCase().includes(query.toLowerCase())),\n  bootstrap: () => items.slice(0, 5),\n};\n\nexport default function TypeaheadWithHelperText() {\n  const [value, setValue] = useState<SearchableItem | null>(null);\n  return (\n    <Center width={320}>\n      <Typeahead\n        label=\"Department\"\n        placeholder=\"Search departments...\"\n        searchSource={searchSource}\n        value={value}\n        onChange={setValue}\n        description=\"Select the department this request should be routed to\"\n      />\n    </Center>\n  );\n}\n","/templates/TypeaheadWithValidation/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {Typeahead} from '@astryxdesign/core/Typeahead';\nimport type {SearchableItem, SearchSource} from '@astryxdesign/core/Typeahead';\nimport {Center} from '@astryxdesign/core/Center';\n\nconst items: SearchableItem[] = [\n  {id: '1', label: 'New York'},\n  {id: '2', label: 'San Francisco'},\n  {id: '3', label: 'London'},\n  {id: '4', label: 'Berlin'},\n  {id: '5', label: 'Tokyo'},\n  {id: '6', label: 'Singapore'},\n  {id: '7', label: 'Sydney'},\n  {id: '8', label: 'Toronto'},\n];\n\nconst searchSource: SearchSource = {\n  search: (query: string) =>\n    items.filter(i => i.label.toLowerCase().includes(query.toLowerCase())),\n  bootstrap: () => items.slice(0, 5),\n};\n\nexport default function TypeaheadWithValidation() {\n  const [value, setValue] = useState<SearchableItem | null>(null);\n  return (\n    <Center width={320}>\n      <Typeahead\n        label=\"Office\"\n        placeholder=\"Search offices...\"\n        searchSource={searchSource}\n        value={value}\n        onChange={setValue}\n        status={{type: 'error', message: 'Please select an office location'}}\n      />\n    </Center>\n  );\n}\n","/templates/TypeaheadItemShowcase/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {Typeahead, TypeaheadItem} from '@astryxdesign/core/Typeahead';\nimport type {SearchableItem, SearchSource} from '@astryxdesign/core/Typeahead';\nimport {Avatar} from '@astryxdesign/core/Avatar';\nimport {Center} from '@astryxdesign/core/Center';\n\ninterface PersonItem extends SearchableItem {\n  auxiliaryData: {role: string};\n}\n\nconst people: PersonItem[] = [\n  {id: '1', label: 'Alice Johnson', auxiliaryData: {role: 'Engineer'}},\n  {id: '2', label: 'Bob Smith', auxiliaryData: {role: 'Designer'}},\n  {id: '3', label: 'Charlie Brown', auxiliaryData: {role: 'Product Manager'}},\n  {id: '4', label: 'Diana Prince', auxiliaryData: {role: 'Data Scientist'}},\n  {id: '5', label: 'Eve Davis', auxiliaryData: {role: 'QA Engineer'}},\n];\n\nconst peopleSource: SearchSource<PersonItem> = {\n  search: (query: string) =>\n    people.filter(p => p.label.toLowerCase().includes(query.toLowerCase())),\n  bootstrap: () => people.slice(0, 4),\n};\n\nexport default function TypeaheadItemShowcase() {\n  const [value, setValue] = useState<PersonItem | null>(null);\n\n  return (\n    <Center width={320}>\n      <Typeahead\n        label=\"Assignee\"\n        placeholder=\"Search people...\"\n        searchSource={peopleSource}\n        value={value}\n        onChange={setValue}\n        renderItem={(item: PersonItem) => (\n          <TypeaheadItem\n            item={item}\n            icon={<Avatar name={item.label} size=\"md\" />}\n            description={item.auxiliaryData.role}\n          />\n        )}\n      />\n    </Center>\n  );\n}\n","/templates/TypeaheadItemBasic/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {Typeahead, TypeaheadItem} from '@astryxdesign/core/Typeahead';\nimport type {SearchableItem, SearchSource} from '@astryxdesign/core/Typeahead';\nimport {Center} from '@astryxdesign/core/Center';\n\ninterface PersonItem extends SearchableItem {\n  auxiliaryData: {role: string};\n}\n\nconst people: PersonItem[] = [\n  {id: '1', label: 'Alice Johnson', auxiliaryData: {role: 'Engineer'}},\n  {id: '2', label: 'Bob Smith', auxiliaryData: {role: 'Designer'}},\n  {id: '3', label: 'Charlie Brown', auxiliaryData: {role: 'Product Manager'}},\n];\n\nconst peopleSource: SearchSource<PersonItem> = {\n  search: (query: string) =>\n    people.filter(p => p.label.toLowerCase().includes(query.toLowerCase())),\n  bootstrap: () => people,\n};\n\nexport default function TypeaheadItemBasic() {\n  const [value, setValue] = useState<PersonItem | null>(null);\n\n  return (\n    <Center width={320}>\n      <Typeahead\n        label=\"Assignee\"\n        placeholder=\"Search people...\"\n        searchSource={peopleSource}\n        value={value}\n        onChange={setValue}\n        renderItem={(item: PersonItem) => (\n          <TypeaheadItem item={item} description={item.auxiliaryData.role} />\n        )}\n      />\n    </Center>\n  );\n}\n","/templates/AppShellMobileHookUsage/":'// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n\'use client\';\n\nimport {useAppShellMobile} from \'@astryxdesign/core/AppShell\';\nimport {Button} from \'@astryxdesign/core/Button\';\nimport {HStack, VStack} from \'@astryxdesign/core/Layout\';\nimport {Text} from \'@astryxdesign/core/Text\';\n\nexport default function AppShellMobileHookUsage() {\n  const {\n    closeMobileNav,\n    isMobile,\n    isMobileNavEnabled,\n    isMobileNavOpen,\n    openMobileNav,\n  } = useAppShellMobile();\n\n  if (!isMobileNavEnabled) {\n    return (\n      <VStack gap={2}>\n        <Button label="Open navigation" variant="secondary" isDisabled />\n        <Text type="body" color="secondary">\n          No active AppShell mobile navigation context was detected. This hook\n          returns safe defaults outside AppShell, or when the surrounding\n          AppShell has mobile navigation disabled.\n        </Text>\n      </VStack>\n    );\n  }\n\n  if (!isMobile) {\n    return (\n      <VStack gap={2}>\n        <Button label="Open navigation" variant="secondary" isDisabled />\n        <Text type="body" color="secondary">\n          AppShell mobile navigation context is available. Narrow the viewport\n          below the AppShell mobile breakpoint to make the custom trigger\n          active.\n        </Text>\n      </VStack>\n    );\n  }\n\n  return (\n    <VStack gap={2}>\n      <HStack gap={2} vAlign="center">\n        <Button\n          label={isMobileNavOpen ? \'Close navigation\' : \'Open navigation\'}\n          variant="secondary"\n          onClick={isMobileNavOpen ? closeMobileNav : openMobileNav}\n        />\n        <Text type="body" color="secondary">\n          {isMobileNavOpen ? \'Mobile nav is open\' : \'Mobile nav is closed\'}\n        </Text>\n      </HStack>\n      <Text type="body" color="secondary">\n        This button controls the nearest AppShell mobile nav from context; in\n        the docsite it opens and closes the surrounding page navigation.\n      </Text>\n    </VStack>\n  );\n}\n',"/templates/CollapsibleHookUsage/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useId} from 'react';\nimport {useCollapsible} from '@astryxdesign/core/Collapsible';\nimport {Button} from '@astryxdesign/core/Button';\nimport {Card} from '@astryxdesign/core/Card';\nimport {VStack} from '@astryxdesign/core/Layout';\nimport {Text} from '@astryxdesign/core/Text';\n\nexport default function CollapsibleHookUsage() {\n  const detailsId = useId();\n  const disclosure = useCollapsible({\n    isCollapsible: {defaultIsOpen: true},\n    value: 'release-notes',\n  });\n\n  return (\n    <Card width={360} padding={4}>\n      <VStack gap={3}>\n        <Text type=\"body\" weight=\"bold\">\n          Release checklist\n        </Text>\n        <Button\n          label={disclosure.isOpen ? 'Hide details' : 'Show details'}\n          variant=\"secondary\"\n          aria-controls={detailsId}\n          aria-expanded={disclosure.isOpen}\n          onClick={disclosure.toggle}\n        />\n        {disclosure.isOpen && (\n          <div\n            id={detailsId}\n            role=\"region\"\n            aria-label=\"Release checklist details\">\n            <Text type=\"body\" color=\"secondary\">\n              Review docs, run visual checks, and confirm keyboard behavior\n              before shipping the component update.\n            </Text>\n          </div>\n        )}\n      </VStack>\n    </Card>\n  );\n}\n","/templates/useContainerRevealHookUsage/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport * as stylex from '@stylexjs/stylex';\nimport {useContainerReveal} from '@astryxdesign/core/hooks';\nimport {Button} from '@astryxdesign/core/Button';\nimport {Card} from '@astryxdesign/core/Card';\nimport {Icon} from '@astryxdesign/core/Icon';\nimport {Item} from '@astryxdesign/core/Item';\nimport {Stack} from '@astryxdesign/core/Layout';\nimport {Text} from '@astryxdesign/core/Text';\nimport {mergeProps} from '@astryxdesign/core/utils';\nimport {PencilIcon, TrashIcon} from '@heroicons/react/24/outline';\n\nconst styles = stylex.create({\n  actions: {\n    display: 'flex',\n    gap: 4,\n  },\n  intro: {\n    paddingInline: 12,\n    paddingBottom: 8,\n  },\n});\n\nfunction FileRow({name}: {name: string}) {\n  // Destructure the two prop getters. Spreading getContainerProps() on the row\n  // gives it a scoped hover/focus-within trigger; getContentRevealProps() hides\n  // the actions at rest and reveals them when the row is hovered or focused.\n  const {getContainerProps, getContentRevealProps} = useContainerReveal();\n\n  return (\n    <Item\n      label={name}\n      description=\"Edited 2 hours ago\"\n      endContent={\n        <span\n          {...mergeProps(\n            getContentRevealProps(),\n            stylex.props(styles.actions),\n          )}>\n          <Button\n            label={`Edit ${name}`}\n            variant=\"ghost\"\n            isIconOnly\n            icon={<Icon icon={PencilIcon} size=\"sm\" />}\n          />\n          <Button\n            label={`Delete ${name}`}\n            variant=\"ghost\"\n            isIconOnly\n            icon={<Icon icon={TrashIcon} size=\"sm\" />}\n          />\n        </span>\n      }\n      {...getContainerProps()}\n    />\n  );\n}\n\nexport default function UseContainerRevealHookUsage() {\n  return (\n    <Card width={420} padding={2}>\n      <Stack gap={0}>\n        <Text type=\"supporting\" color=\"secondary\" xstyle={styles.intro}>\n          Hover a row — or Tab into it — to reveal its actions. On touch they\n          stay visible.\n        </Text>\n        <FileRow name=\"report.pdf\" />\n        <FileRow name=\"budget.xlsx\" />\n        <FileRow name=\"notes.txt\" />\n      </Stack>\n    </Card>\n  );\n}\n","/templates/HoverCardHookUsage/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useHoverCard} from '@astryxdesign/core/HoverCard';\nimport {Button} from '@astryxdesign/core/Button';\nimport {Center} from '@astryxdesign/core/Center';\nimport {VStack} from '@astryxdesign/core/Layout';\nimport {Text} from '@astryxdesign/core/Text';\n\nexport default function HoverCardHookUsage() {\n  const hoverCard = useHoverCard({\n    placement: 'below',\n    delay: 100,\n    isDefaultOpen: true,\n    label: 'Alex Morgan',\n  });\n\n  return (\n    <Center height={220}>\n      <Button\n        label=\"Hover profile\"\n        ref={hoverCard.ref}\n        aria-haspopup=\"dialog\"\n        aria-controls={hoverCard.isOpen ? hoverCard.id : undefined}\n        aria-expanded={hoverCard.isOpen}\n      />\n      {hoverCard.renderHoverCard(\n        <VStack gap={1}>\n          <Text type=\"body\" weight=\"bold\">\n            Alex Morgan\n          </Text>\n          <Text type=\"body\" color=\"secondary\">\n            Staff designer \xb7 Product systems\n          </Text>\n          <Text type=\"body\" color=\"secondary\">\n            Owns interaction patterns for overlays and navigation.\n          </Text>\n        </VStack>,\n        {placement: 'below', alignment: 'center'},\n      )}\n    </Center>\n  );\n}\n","/templates/useKeyboardHintHookUsage/":'// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n\'use client\';\n\nimport {Toolbar} from \'@astryxdesign/core/Toolbar\';\nimport {Button} from \'@astryxdesign/core/Button\';\nimport {Icon} from \'@astryxdesign/core/Icon\';\nimport {Card} from \'@astryxdesign/core/Card\';\nimport {Section} from \'@astryxdesign/core/Section\';\nimport {Text} from \'@astryxdesign/core/Text\';\nimport {VStack} from \'@astryxdesign/core/Layout\';\nimport {BoldIcon, ItalicIcon, UnderlineIcon} from \'@heroicons/react/24/outline\';\n\nexport default function UseKeyboardHintHookUsage() {\n  return (\n    <Card style={{width: 420}}>\n      <Toolbar\n        label="Text formatting"\n        dividers={[\'bottom\']}\n        startContent={\n          <>\n            <Button\n              label="Bold"\n              variant="ghost"\n              icon={<Icon icon={BoldIcon} />}\n              isIconOnly\n            />\n            <Button\n              label="Italic"\n              variant="ghost"\n              icon={<Icon icon={ItalicIcon} />}\n              isIconOnly\n            />\n            <Button\n              label="Underline"\n              variant="ghost"\n              icon={<Icon icon={UnderlineIcon} />}\n              isIconOnly\n            />\n          </>\n        }\n      />\n      <Section>\n        <VStack gap={1}>\n          <Text type="body" weight="bold">\n            Keyboard-friendly by default\n          </Text>\n          <Text type="supporting" color="secondary">\n            Tab into the toolbar with your keyboard and Toolbar shows an\n            ephemeral "← → to navigate" hint — powered by useKeyboardHint — so\n            sighted keyboard users learn that arrows move within the group.\n          </Text>\n        </VStack>\n      </Section>\n    </Card>\n  );\n}\n',"/templates/LayerHookUsage/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useLayer} from '@astryxdesign/core/Layer';\nimport {Button} from '@astryxdesign/core/Button';\nimport {Card} from '@astryxdesign/core/Card';\nimport {Center} from '@astryxdesign/core/Center';\nimport {VStack} from '@astryxdesign/core/Layout';\nimport {Text} from '@astryxdesign/core/Text';\n\nexport default function LayerHookUsage() {\n  const layer = useLayer({mode: 'context', lightDismiss: true});\n\n  return (\n    <Center height={220}>\n      <Button\n        label={layer.isOpen ? 'Hide layer' : 'Show layer'}\n        ref={layer.ref}\n        onClick={layer.isOpen ? layer.hide : layer.show}\n      />\n      {layer.render(\n        <Card padding={3}>\n          <VStack gap={1}>\n            <Text type=\"body\" weight=\"bold\">\n              Anchored content\n            </Text>\n            <Text type=\"body\" color=\"secondary\">\n              useLayer provides positioning; you own semantics and surface.\n            </Text>\n          </VStack>\n        </Card>,\n        {placement: 'below', alignment: 'center'},\n      )}\n    </Center>\n  );\n}\n","/templates/PopoverHookUsage/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {usePopover} from '@astryxdesign/core/Popover';\nimport {Button} from '@astryxdesign/core/Button';\nimport {Card} from '@astryxdesign/core/Card';\nimport {Center} from '@astryxdesign/core/Center';\nimport {VStack} from '@astryxdesign/core/Layout';\nimport {Text} from '@astryxdesign/core/Text';\n\nexport default function PopoverHookUsage() {\n  const popover = usePopover({dialogLabel: 'Quick actions'});\n\n  return (\n    <Center height={240}>\n      <Button\n        label=\"Open actions\"\n        ref={popover.triggerRef}\n        onClick={popover.toggle}\n        {...popover.triggerProps}\n      />\n      {popover.render(\n        <Card width={220} padding={3} variant=\"transparent\">\n          <VStack gap={2}>\n            <Text type=\"body\" weight=\"bold\">\n              Quick actions\n            </Text>\n            <Button label=\"Create task\" size=\"sm\" />\n            <Button label=\"Share report\" variant=\"secondary\" size=\"sm\" />\n          </VStack>\n        </Card>,\n        {placement: 'below', alignment: 'center'},\n      )}\n    </Center>\n  );\n}\n","/templates/useStreamingTextHookUsage/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useStreamingText} from '@astryxdesign/core/hooks';\nimport {Card} from '@astryxdesign/core/Card';\nimport {VStack} from '@astryxdesign/core/Layout';\nimport {Text} from '@astryxdesign/core/Text';\n\nconst response =\n  'Astryx hooks keep behavior reusable while components keep visuals consistent.';\n\nexport default function UseStreamingTextHookUsage() {\n  const displayedText = useStreamingText(response, false, {\n    speed: 'fast',\n  });\n\n  return (\n    <Card width={420} padding={4}>\n      <VStack gap={2}>\n        <Text type=\"body\" weight=\"bold\">\n          Assistant response\n        </Text>\n        <Text type=\"body\">{displayedText}</Text>\n        <Text type=\"supporting\" color=\"secondary\">\n          Complete\n        </Text>\n      </VStack>\n    </Card>\n  );\n}\n","/templates/ColumnResizeHookUsage/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {\n  Table,\n  useTableColumnResize,\n  proportional,\n  pixel,\n} from '@astryxdesign/core/Table';\n\ninterface User extends Record<string, unknown> {\n  id: string;\n  name: string;\n  email: string;\n  role: string;\n}\n\nconst users: User[] = [\n  {\n    id: '1',\n    name: 'Alice Johnson',\n    email: 'alice@example.com',\n    role: 'Engineer',\n  },\n  {id: '2', name: 'Bob Smith', email: 'bob@example.com', role: 'Designer'},\n  {id: '3', name: 'Charlie Brown', email: 'charlie@example.com', role: 'PM'},\n  {id: '4', name: 'Diana Prince', email: 'diana@example.com', role: 'Engineer'},\n  {id: '5', name: 'Eve Davis', email: 'eve@example.com', role: 'Analyst'},\n];\n\nconst columns = [\n  {key: 'name', header: 'Name'},\n  {key: 'email', header: 'Email', width: proportional(2)},\n  {key: 'role', header: 'Role', width: pixel(120)},\n];\n\nexport default function ColumnResizeHookUsage() {\n  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});\n\n  const columnResize = useTableColumnResize({\n    columnWidths,\n    columns,\n    onColumnResizeEnd: updates => {\n      setColumnWidths(prev => ({...prev, ...updates}));\n    },\n  });\n\n  return (\n    <Table\n      data={users}\n      columns={columns}\n      idKey=\"id\"\n      hasHover\n      plugins={{columnResize}}\n    />\n  );\n}\n","/templates/TableGroupedRowsTable/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState, useCallback} from 'react';\nimport {\n  Table,\n  useTableGroupedRows,\n  proportional,\n  pixel,\n} from '@astryxdesign/core/Table';\nimport type {TableColumn} from '@astryxdesign/core/Table';\n\ninterface Person extends Record<string, unknown> {\n  id: string;\n  name: string;\n  team: string;\n  role: string;\n}\n\nconst people: Person[] = [\n  {id: '1', name: 'Ava Chen', team: 'Design Systems', role: 'Staff Eng'},\n  {id: '2', name: 'Liam Park', team: 'Design Systems', role: 'Engineer'},\n  {id: '3', name: 'Zoe Vega', team: 'Design Systems', role: 'Manager'},\n  {id: '4', name: 'Max Ross', team: 'Infra', role: 'Senior Eng'},\n  {id: '5', name: 'Mia Cole', team: 'Infra', role: 'Engineer'},\n  {id: '6', name: 'Leo Nash', team: 'Growth', role: 'PM'},\n];\n\nconst columns: TableColumn<Person>[] = [\n  {key: 'name', header: 'Name', width: proportional(2)},\n  {key: 'role', header: 'Role', width: pixel(140)},\n];\n\nexport default function TableGroupedRowsTable() {\n  const [collapsedGroups, setCollapsed] = useState<Set<string>>(new Set());\n  const onToggleGroup = useCallback((key: string) => {\n    setCollapsed(prev => {\n      const next = new Set(prev);\n      if (next.has(key)) {\n        next.delete(key);\n      } else {\n        next.add(key);\n      }\n      return next;\n    });\n  }, []);\n\n  const grouped = useTableGroupedRows<Person>({\n    data: people,\n    groupBy: p => p.team,\n    collapsedGroups,\n    onToggleGroup,\n    getRowKey: p => p.id,\n  });\n\n  return (\n    <Table\n      data={grouped.data}\n      columns={columns}\n      idKey={grouped.idKey}\n      hasHover\n      plugins={{grouped: grouped.plugin}}\n    />\n  );\n}\n","/templates/TableRowExpansionTable/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {useState} from 'react';\nimport {\n  Table,\n  useTableRowExpansion,\n  proportional,\n  pixel,\n} from '@astryxdesign/core/Table';\nimport {VStack, HStack} from '@astryxdesign/core/Stack';\nimport {Text, Heading} from '@astryxdesign/core/Text';\nimport {Badge} from '@astryxdesign/core/Badge';\n\ninterface Order extends Record<string, unknown> {\n  id: string;\n  customer: string;\n  status: string;\n  total: string;\n  items: {name: string; qty: number; price: string}[];\n}\n\nconst orders: Order[] = [\n  {\n    id: 'ord-1001',\n    customer: 'Ada Lovelace',\n    status: 'Shipped',\n    total: '$248.00',\n    items: [\n      {name: 'Mechanical keyboard', qty: 1, price: '$180.00'},\n      {name: 'Wrist rest', qty: 2, price: '$34.00'},\n    ],\n  },\n  {\n    id: 'ord-1002',\n    customer: 'Alan Turing',\n    status: 'Processing',\n    total: '$52.00',\n    items: [{name: 'USB-C cable', qty: 4, price: '$13.00'}],\n  },\n  {\n    id: 'ord-1003',\n    customer: 'Grace Hopper',\n    status: 'Delivered',\n    total: '$1,200.00',\n    items: [{name: 'Standing desk', qty: 1, price: '$1,200.00'}],\n  },\n];\n\nconst columns = [\n  {key: 'customer', header: 'Customer', width: proportional(2)},\n  {key: 'status', header: 'Status', width: pixel(130)},\n  {key: 'total', header: 'Total', width: pixel(110)},\n];\n\nexport default function TableRowExpansionTable() {\n  const [expandedKeys, setExpandedKeys] = useState<Set<string>>(\n    new Set(['ord-1001']),\n  );\n\n  const expansion = useTableRowExpansion<Order>({\n    expandedKeys,\n    onToggle: key =>\n      setExpandedKeys(prev => {\n        const next = new Set(prev);\n        if (next.has(key)) {\n          next.delete(key);\n        } else {\n          next.add(key);\n        }\n        return next;\n      }),\n    getRowKey: item => item.id,\n    // The detail panel renders arbitrary content below the row: here, the\n    // order's line items. Any component composes here (charts, forms, tables).\n    renderExpanded: item => (\n      <VStack gap={2}>\n        <Heading level={4}>Line items</Heading>\n        {item.items.map(line => (\n          <HStack key={line.name} gap={3}>\n            <Badge label={`x${line.qty}`} variant=\"info\" />\n            <Text type=\"body\">{line.name}</Text>\n            <Text type=\"body\" color=\"secondary\">\n              {line.price}\n            </Text>\n          </HStack>\n        ))}\n      </VStack>\n    ),\n  });\n\n  return (\n    <Table\n      data={orders}\n      columns={columns}\n      idKey=\"id\"\n      hasHover\n      plugins={{expansion}}\n    />\n  );\n}\n","/templates/TableRowIndexTable/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {\n  Table,\n  useTableRowIndex,\n  proportional,\n  pixel,\n} from '@astryxdesign/core/Table';\nimport type {TableColumn} from '@astryxdesign/core/Table';\n\ninterface Track extends Record<string, unknown> {\n  id: string;\n  title: string;\n  artist: string;\n  plays: number;\n}\n\nconst tracks: Track[] = [\n  {id: 't1', title: 'Nightfall', artist: 'Ava Chen', plays: 1820},\n  {id: 't2', title: 'Ember', artist: 'Liam Park', plays: 942},\n  {id: 't3', title: 'Tidal', artist: 'Zoe Vega', plays: 3310},\n  {id: 't4', title: 'Cinder', artist: 'Max Ross', plays: 604},\n  {id: 't5', title: 'Halcyon', artist: 'Mia Cole', plays: 2075},\n];\n\nconst columns: TableColumn<Track>[] = [\n  {key: 'title', header: 'Title', width: proportional(2)},\n  {key: 'artist', header: 'Artist', width: proportional(2)},\n  {key: 'plays', header: 'Plays', width: pixel(90), align: 'end'},\n];\n\nexport default function TableRowIndexTable() {\n  // Pass the rendered data array — numbering follows its order.\n  const rowIndex = useTableRowIndex<Track>({data: tracks});\n\n  return (\n    <Table\n      data={tracks}\n      columns={columns}\n      idKey=\"id\"\n      hasHover\n      plugins={{rowIndex}}\n    />\n  );\n}\n","/templates/TableRowStatusTable/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {\n  Table,\n  useTableRowStatus,\n  proportional,\n  pixel,\n} from '@astryxdesign/core/Table';\nimport type {\n  TableColumn,\n  UseTableRowStatusConfig,\n} from '@astryxdesign/core/Table';\n\ninterface Job extends Record<string, unknown> {\n  id: string;\n  name: string;\n  owner: string;\n  state: 'failed' | 'running' | 'queued' | 'succeeded' | 'needsAttention';\n}\n\nconst jobs: Job[] = [\n  {id: 'j1', name: 'build-core', owner: 'Ava', state: 'failed'},\n  {id: 'j2', name: 'lint', owner: 'Liam', state: 'running'},\n  {id: 'j3', name: 'unit-tests', owner: 'Zoe', state: 'succeeded'},\n  {id: 'j4', name: 'docsite-deploy', owner: 'Max', state: 'queued'},\n  {id: 'j5', name: 'smoke-test', owner: 'Mia', state: 'succeeded'},\n  {\n    id: 'j6',\n    name: 'snapshot-review',\n    owner: 'Noah',\n    state: 'needsAttention',\n  },\n];\n\nconst columns: TableColumn<Job>[] = [\n  {key: 'name', header: 'Job', width: proportional(2)},\n  {key: 'owner', header: 'Owner', width: pixel(120)},\n  {key: 'state', header: 'State', width: pixel(120)},\n];\n\nconst jobStatus: UseTableRowStatusConfig<Job>['getStatus'] = job => {\n  switch (job.state) {\n    case 'failed':\n      return {status: 'error', label: 'Failed'};\n    case 'running':\n      return {color: 'warning', icon: 'clock', label: 'Running'};\n    case 'queued':\n      return {color: 'gray', label: 'Queued'};\n    case 'succeeded':\n      return {status: 'success', label: 'Succeeded'};\n    case 'needsAttention':\n      return {status: 'warning', label: 'Needs attention'};\n  }\n};\n\nexport default function TableRowStatusTable() {\n  const rowStatus = useTableRowStatus<Job>({getStatus: jobStatus});\n\n  return (\n    <Table\n      data={jobs}\n      columns={columns}\n      idKey=\"id\"\n      hasHover\n      plugins={{rowStatus}}\n    />\n  );\n}\n","/templates/StickyColumnsHookUsage/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {Table, useTableStickyColumns, pixel} from '@astryxdesign/core/Table';\n\ninterface Employee extends Record<string, unknown> {\n  id: string;\n  name: string;\n  email: string;\n  team: string;\n  role: string;\n  location: string;\n  startDate: string;\n  status: string;\n}\n\nconst employees: Employee[] = [\n  {\n    id: '1',\n    name: 'Alice Johnson',\n    email: 'alice@example.com',\n    team: 'Design Systems',\n    role: 'Staff Engineer',\n    location: 'San Francisco',\n    startDate: '2019-03-12',\n    status: 'Active',\n  },\n  {\n    id: '2',\n    name: 'Bob Smith',\n    email: 'bob@example.com',\n    team: 'Design Systems',\n    role: 'Senior Designer',\n    location: 'New York',\n    startDate: '2020-07-01',\n    status: 'Active',\n  },\n  {\n    id: '3',\n    name: 'Charlie Brown',\n    email: 'charlie@example.com',\n    team: 'Platform',\n    role: 'Engineering Manager',\n    location: 'London',\n    startDate: '2017-11-20',\n    status: 'On leave',\n  },\n  {\n    id: '4',\n    name: 'Diana Prince',\n    email: 'diana@example.com',\n    team: 'Platform',\n    role: 'Staff Engineer',\n    location: 'Remote',\n    startDate: '2021-01-15',\n    status: 'Active',\n  },\n  {\n    id: '5',\n    name: 'Eve Davis',\n    email: 'eve@example.com',\n    team: 'Growth',\n    role: 'Product Engineer',\n    location: 'Berlin',\n    startDate: '2022-05-30',\n    status: 'Active',\n  },\n];\n\n// Wide fixed-width columns so the table overflows and scrolls horizontally,\n// keeping the pinned Name (start) and Status (end) columns in view.\nconst columns = [\n  {key: 'name', header: 'Name', width: pixel(180)},\n  {key: 'email', header: 'Email', width: pixel(220)},\n  {key: 'team', header: 'Team', width: pixel(180)},\n  {key: 'role', header: 'Role', width: pixel(200)},\n  {key: 'location', header: 'Location', width: pixel(160)},\n  {key: 'startDate', header: 'Start date', width: pixel(140)},\n  {key: 'status', header: 'Status', width: pixel(140)},\n];\n\nexport default function StickyColumnsHookUsage() {\n  const stickyColumns = useTableStickyColumns<Employee>({\n    startKeys: ['name'],\n    endKeys: ['status'],\n  });\n\n  return (\n    // Constrain the width so the Table's own horizontal scroll container is\n    // narrower than its columns — that scroll container is what sticky columns\n    // pin against. Without a width cap the table renders full-width and never\n    // scrolls internally, so nothing sticks.\n    <div style={{width: 560, maxWidth: '100%'}}>\n      <Table\n        data={employees}\n        columns={columns}\n        idKey=\"id\"\n        hasHover\n        plugins={{stickyColumns}}\n      />\n    </div>\n  );\n}\n","/templates/TableTreeTable/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {\n  Table,\n  useTableTreeData,\n  useTableTreeState,\n  proportional,\n  pixel,\n} from '@astryxdesign/core/Table';\n\ninterface FileNode extends Record<string, unknown> {\n  id: string;\n  name: string;\n  kind: 'folder' | 'file';\n  size: string;\n  children?: FileNode[];\n}\n\nconst fileTree: FileNode[] = [\n  {\n    id: 'src',\n    name: 'src',\n    kind: 'folder',\n    size: '',\n    children: [\n      {\n        id: 'src/components',\n        name: 'components',\n        kind: 'folder',\n        size: '',\n        children: [\n          {\n            id: 'src/components/Button.tsx',\n            name: 'Button.tsx',\n            kind: 'file',\n            size: '4.2 KB',\n          },\n          {\n            id: 'src/components/Table.tsx',\n            name: 'Table.tsx',\n            kind: 'file',\n            size: '12.8 KB',\n          },\n        ],\n      },\n      {id: 'src/index.ts', name: 'index.ts', kind: 'file', size: '0.4 KB'},\n    ],\n  },\n  {id: 'package.json', name: 'package.json', kind: 'file', size: '1.8 KB'},\n];\n\nconst columns = [\n  {key: 'name', header: 'Name', width: proportional(2)},\n  {key: 'kind', header: 'Kind', width: pixel(90)},\n  {key: 'size', header: 'Size', width: pixel(90)},\n];\n\nexport default function TableTreeTable() {\n  // useTableTreeState owns the expanded set and flattens the nested data into\n  // the visible rows; useTableTreeData draws the indent + expander in the tree\n  // column. hasExpandAllControl adds the expand-all toggle to the header.\n  const {visibleData, treeConfig} = useTableTreeState<FileNode>({\n    data: fileTree,\n    idKey: 'id',\n    defaultExpandedIds: ['src'],\n  });\n\n  const tree = useTableTreeData({...treeConfig, hasExpandAllControl: true});\n\n  return (\n    <Table\n      data={visibleData}\n      columns={columns}\n      idKey=\"id\"\n      hasHover\n      plugins={{tree}}\n    />\n  );\n}\n","/templates/useThemeHookUsage/":'// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n\'use client\';\n\nimport {useTheme} from \'@astryxdesign/core/theme\';\nimport {Card} from \'@astryxdesign/core/Card\';\nimport {HStack, VStack} from \'@astryxdesign/core/Layout\';\nimport {Text} from \'@astryxdesign/core/Text\';\n\nexport default function UseThemeHookUsage() {\n  const {name, mode, token} = useTheme();\n  const accent = token(\'--color-accent\');\n  const muted = token(\'--color-accent-muted\');\n  const text = token(\'--color-text-primary\');\n\n  return (\n    <Card width={360} padding={4}>\n      <VStack gap={3}>\n        <Text type="body" weight="bold">\n          {name} \xb7 {mode}\n        </Text>\n        <svg width="300" height="120" role="img" aria-label="Themed bar chart">\n          <rect x="24" y="20" width="64" height="80" rx="8" fill={accent} />\n          <rect x="118" y="48" width="64" height="52" rx="8" fill={muted} />\n          <rect\n            x="212"\n            y="32"\n            width="64"\n            height="68"\n            rx="8"\n            fill={accent}\n            opacity="0.72"\n          />\n          <text x="24" y="114" fill={text} fontSize="12">\n            Resolved token values\n          </text>\n        </svg>\n        <HStack gap={2}>\n          <Text type="code">--color-accent</Text>\n          <Text type="code" color="secondary">\n            {accent}\n          </Text>\n        </HStack>\n      </VStack>\n    </Card>\n  );\n}\n',"/templates/VisuallyHiddenShowcase/":'// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n\'use client\';\n\nimport {VisuallyHidden} from \'@astryxdesign/core/VisuallyHidden\';\nimport {IconButton} from \'@astryxdesign/core/IconButton\';\nimport {Card} from \'@astryxdesign/core/Card\';\nimport {HStack, VStack} from \'@astryxdesign/core/Layout\';\nimport {Text} from \'@astryxdesign/core/Text\';\nimport {Icon} from \'@astryxdesign/core/Icon\';\nimport {\n  ArrowDownTrayIcon,\n  ShareIcon,\n  TrashIcon,\n} from \'@heroicons/react/24/outline\';\nimport {SpeakerWaveIcon} from \'@heroicons/react/24/solid\';\n\nconst actions = [\n  {label: \'Download\', icon: ArrowDownTrayIcon},\n  {label: \'Share\', icon: ShareIcon},\n  {label: \'Delete\', icon: TrashIcon},\n] as const;\n\n/**\n * VisuallyHidden is invisible by design, so this hero teaches the concept by\n * contrast: the icon-only buttons are all a sighted user sees, while the\n * caption spells out the accessible name each one exposes. A live\n * <VisuallyHidden> region below announces the same names to assistive tech,\n * so the demo genuinely exercises the component it documents.\n */\nexport default function VisuallyHiddenShowcase() {\n  return (\n    <VStack gap={5} hAlign="center">\n      <HStack gap={6} vAlign="stretch" wrap="wrap" hAlign="center">\n        <Card variant="muted">\n          <VStack gap={4} hAlign="center">\n            <Text type="supporting" color="secondary">\n              What you see\n            </Text>\n            <HStack gap={2}>\n              {actions.map(({label, icon}) => (\n                <IconButton\n                  key={label}\n                  label={label}\n                  icon={<Icon icon={icon} />}\n                  variant="ghost"\n                />\n              ))}\n            </HStack>\n          </VStack>\n        </Card>\n\n        <Card variant="muted">\n          <VStack gap={4} hAlign="start">\n            <HStack gap={2} vAlign="center">\n              <Icon icon={SpeakerWaveIcon} size="sm" />\n              <Text type="supporting" color="secondary">\n                What a screen reader hears\n              </Text>\n            </HStack>\n            <VStack gap={2}>\n              {actions.map(({label}) => (\n                <Text key={label} type="body">\n                  {label}, button\n                </Text>\n              ))}\n            </VStack>\n          </VStack>\n        </Card>\n      </HStack>\n\n      {/* A real live region: silent to sighted users, announced by AT. */}\n      <VisuallyHidden as="div" aria-live="polite">\n        Actions available: Download, Share, Delete.\n      </VisuallyHidden>\n    </VStack>\n  );\n}\n',"/templates/VisuallyHiddenLiveRegion/":'// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n\'use client\';\n\nimport {useState} from \'react\';\nimport {VisuallyHidden} from \'@astryxdesign/core/VisuallyHidden\';\nimport {Button} from \'@astryxdesign/core/Button\';\nimport {HStack, VStack} from \'@astryxdesign/core/Layout\';\nimport {Text} from \'@astryxdesign/core/Text\';\n\nconst columns = [\'Backlog\', \'In progress\', \'Done\'] as const;\n\nexport default function VisuallyHiddenLiveRegion() {\n  const [column, setColumn] = useState(0);\n  const current = columns[column];\n\n  function move() {\n    setColumn(c => (c + 1) % columns.length);\n  }\n\n  return (\n    <VStack gap={4} hAlign="start">\n      <Text type="supporting" color="secondary">\n        Drag-and-drop and other visual-only changes are silent to screen\n        readers. A live region narrates them.\n      </Text>\n      <HStack gap={3} vAlign="center">\n        <Button label="Move task" variant="secondary" onClick={move} />\n        <Text type="body">\n          Task is in{\' \'}\n          <Text as="span" weight="bold">\n            {current}\n          </Text>\n        </Text>\n      </HStack>\n      <VisuallyHidden as="div" aria-live="polite">\n        {`Task moved to ${current}`}\n      </VisuallyHidden>\n    </VStack>\n  );\n}\n',"/templates/VisuallyHiddenStructuralHeading/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {VisuallyHidden} from '@astryxdesign/core/VisuallyHidden';\nimport {Card} from '@astryxdesign/core/Card';\nimport {HStack, VStack} from '@astryxdesign/core/Layout';\nimport {Text} from '@astryxdesign/core/Text';\nimport {Badge} from '@astryxdesign/core/Badge';\n\nconst items = [\n  {name: 'astryx-core', status: 'Passing', variant: 'success'},\n  {name: 'astryx-charts', status: 'Failing', variant: 'error'},\n  {name: 'astryx-cli', status: 'Passing', variant: 'success'},\n] as const;\n\nexport default function VisuallyHiddenStructuralHeading() {\n  return (\n    <VStack gap={3} hAlign=\"start\">\n      <Text type=\"supporting\" color=\"secondary\">\n        The layout makes this group obvious to sighted users. A hidden heading\n        gives screen-reader users the same landmark to jump to.\n      </Text>\n      {/* No visible heading is needed here, but AT users navigate by heading. */}\n      <VisuallyHidden as=\"h2\">Build status</VisuallyHidden>\n      <VStack gap={2}>\n        {items.map(({name, status, variant}) => (\n          <Card key={name} variant=\"muted\" padding={3}>\n            <HStack gap={3} vAlign=\"center\">\n              <Text type=\"body\">{name}</Text>\n              <Badge label={status} variant={variant} />\n            </HStack>\n          </Card>\n        ))}\n      </VStack>\n    </VStack>\n  );\n}\n","/templates/VisuallyHiddenSupplementaryContext/":"// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n'use client';\n\nimport {VisuallyHidden} from '@astryxdesign/core/VisuallyHidden';\nimport {Card} from '@astryxdesign/core/Card';\nimport {HStack, VStack} from '@astryxdesign/core/Layout';\nimport {Text} from '@astryxdesign/core/Text';\nimport {Icon} from '@astryxdesign/core/Icon';\nimport {ArrowUpIcon, ArrowDownIcon} from '@heroicons/react/24/solid';\n\nconst stats = [\n  {label: 'Revenue', value: '$48.2k', delta: '+12%', direction: 'up'},\n  {label: 'Churn', value: '2.1%', delta: '-4%', direction: 'down'},\n] as const;\n\nexport default function VisuallyHiddenSupplementaryContext() {\n  return (\n    <HStack gap={4} wrap=\"wrap\">\n      {stats.map(({label, value, delta, direction}) => (\n        <Card key={label} variant=\"muted\">\n          <VStack gap={1}>\n            <Text type=\"supporting\" color=\"secondary\">\n              {label}\n            </Text>\n            <Text type=\"display-3\">{value}</Text>\n            <HStack gap={1} vAlign=\"center\">\n              <Icon\n                icon={direction === 'up' ? ArrowUpIcon : ArrowDownIcon}\n                size=\"sm\"\n                color={direction === 'up' ? 'accent' : 'secondary'}\n              />\n              <Text type=\"body\">\n                {delta}\n                {/* The arrow is decorative; spell out the trend for AT. */}\n                <VisuallyHidden>\n                  {direction === 'up' ? ' increase' : ' decrease'} from last\n                  month\n                </VisuallyHidden>\n              </Text>\n            </HStack>\n          </VStack>\n        </Card>\n      ))}\n    </HStack>\n  );\n}\n","/templates/VStackShowcase/":'// Copyright (c) Meta Platforms, Inc. and affiliates.\n\n\'use client\';\n\nimport {HStack, VStack} from \'@astryxdesign/core/Layout\';\nimport {Badge} from \'@astryxdesign/core/Badge\';\nimport {Text} from \'@astryxdesign/core/Text\';\n\nexport default function VStackShowcase() {\n  return (\n    <HStack gap={10} hAlign="center">\n      <VStack gap={2}>\n        <Text type="supporting" color="secondary">\n          gap=2\n        </Text>\n        <VStack gap={2}>\n          <Badge label="Step 1" />\n          <Badge label="Step 2" />\n          <Badge label="Step 3" />\n        </VStack>\n      </VStack>\n      <VStack gap={2}>\n        <Text type="supporting" color="secondary">\n     